import{c as t,Q as o,j as a,m as n}from"./chunks/framework.g_l1frA7.js";const d=JSON.parse('{"title":"Compound Growth","description":"","frontmatter":{},"headers":[],"relativePath":"framework/compound-growth.md","filePath":"framework/compound-growth.md","lastUpdated":null}'),r={name:"framework/compound-growth.md"};function i(s,e,h,l,p,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="compound-growth" tabindex="-1">Compound Growth <a class="header-anchor" href="#compound-growth" aria-label="Permalink to &quot;Compound Growth&quot;">​</a></h1><blockquote><p>Time is the exponent. Small amounts, compounded, become the plan. — <em>Hill</em> / <em>Kiyosaki</em></p></blockquote><h2 id="the-projection" tabindex="-1">The projection <a class="header-anchor" href="#the-projection" aria-label="Permalink to &quot;The projection&quot;">​</a></h2><p>FinSight renders a <strong>10 / 20 / 30-year projection at 7% annual</strong> from the current contribution rate:</p><blockquote><p>“At $500/month, 7% annual, ~$86k in 10 years before inflation.”</p></blockquote><p>It is deterministic arithmetic in <code>metrics</code> / Goals, not a market prediction. The Copilot is instructed to say so and to avoid implying guarantees.</p><h2 id="where-it-appears" tabindex="-1">Where it appears <a class="header-anchor" href="#where-it-appears" aria-label="Permalink to &quot;Where it appears&quot;">​</a></h2><ul><li><strong>Goals</strong> — each funded goal shows the three horizons live as you change the monthly amount.</li><li><strong>Budget forecast</strong> — short-range (this month) vs long-range (decades) are kept separate; the forecast explains burn rate, the projection explains compounding.</li><li><strong>Copilot</strong> — “What does $200/month extra do over 20 years?” returns the delta across horizons with the same 7% assumption.</li></ul><h2 id="using-it" tabindex="-1">Using it <a class="header-anchor" href="#using-it" aria-label="Permalink to &quot;Using it&quot;">​</a></h2><p>Adjust the monthly amount on a goal and watch the long-range figure move. That instant feedback is the point: the habit matters more than the exact rate, and the habit is yours to tune.</p><p>The 7% is a common planning assumption, not a promise. Inflation and fees are not modelled; the inspector makes the assumption explicit.</p>',11)])])}const u=t(r,[["render",i]]);export{d as __pageData,u as default};
